(1, 'Conion 24RB600N HD LED Television 24&amp;quot;', '28735630', 7, 1, 'C128', 1, 12500, 18, 20, 'Conion-24RB600N-HD-LED-Television-908090.jpg', 4.00, NULL, '2', '2', NULL, NULL, NULL, '1', 'Conion 24RB600N HD LED Television available at all the showrooms of Best Electronics in Bangladesh. Equipped with great picture quality and sound system that’ll blow your mind. This 24 inch Smart LED TV equipped with full HD view redefines your TV viewing experience. Never have there been a Smart LED TV with this many features at such an affordable price. Some key features of Conion 24RB600N HD LED Television are:\r\n\r\n    Perfect Resolution & Aspect Ratio ensure the bright picture\r\n    Eye Care Technology protects\r\n    3D Picture Quality\r\n    Dynamic Backlight Adjustment\r\n    Stereo Sound\r\n    USB, HDMI & Earphone Port\r\n    Weak signal auto enhancer\r\n    Quick Response time\r\n\r\nConion is the flagship brand of Best Electronics in Bangladesh. Get your Conion 24RB600N HD LED Television now from your nearest Best Electronics Store and enjoy Easy Installment Payment Facility.', 'Super Admin', 'Super Admin', '2021-12-04 11:17:26', '2021-12-08 16:24:51'),
(2, 'Whirlpool Washing Machine Bloomwash Ultimate Care 14 kg (with Advanced In-Built Heater)', '07151489', 6, 3, 'C128', 1, 50900, 9, 5, 'Whirlpool-Washing-Machine-Bloomwash-Ultimate-Care-14-kg-with-Advanced-In-Built-Heater-300x300-949834.jpg', NULL, NULL, '2', '1', 49900, '2021-12-04', '2021-12-15', '1', NULL, 'Super Admin', 'Super Admin', '2021-12-04 12:35:39', '2021-12-08 16:24:15'),
(3, 'Whirlpool Refrigerator 5WRS22FDBF (Water Dispenser)', '97391235', 6, 2, 'C128', 1, 229500, 10, 20, '5WRS22FDBF-Water-Dispenser-300x300-318252.jpg', NULL, NULL, '2', '1', 98357, '2021-12-05', '2021-12-30', '1', 'Whirlpool Refrigerator 5WRS22FDBF (Water Dispenser) Side by Side refrigerator has just arrived. With the latest technology in efficiency and cooling, this tropicalized designed product is built to handle any environment with the coolest success. With the latest ice maker and water dispenser, it can produce crushed ice & ice cubes without a hitch. Thanks to Whirlpools latest adaptive defrost technology, energy is saved by monitoring the compressor activity and only defrosting when necessary. Along with the latest Accu-Chill Temperature Management System the New Whirlpool 5WRS22FD senses and adapts to the right temperature using built-in sensors to measure the internal temperature of the refrigerator. It activates the compressor only when necessary, saving energy while utilizing the highest efficiency. This stainless steel refrigerator introduces the new sparkle stainless concept, making it a breeze to take care of. So basically, it looks good all of the time, while doing its job to keep your food fresh in the toughest environment.', 'Super Admin', 'Super Admin', '2021-12-04 12:37:19', '2021-12-08 16:19:00'),
(4, 'Hitachi Refrigerator R-W690P7PB (GBK) Water Dispenser', '58619914', 4, 2, 'C128', 1, 165900, 10, NULL, 'sdfdssdf-602324.jpg', NULL, NULL, '2', '2', NULL, NULL, NULL, '1', NULL, 'Super Admin', NULL, '2021-12-07 16:59:58', '2021-12-08 16:19:00'),
